initial_evidence.observer_driver:
from pathlib import Path
import subprocess,os,json,re
p=Path(__file__).parent
b=p/"target/release/examples/line_profile"
reference=json.load(open(p/"reference.json"))
expected={(m["case"],m["length"],int(m["width"])):m["output"] for m in reference["measurements"]}
result=[]
for case,n,width in [("plain",4096,1000000),("emphasis",4096,1000000)]+[("spaces",n,128) for n in (32,64,128,256,512,1024,4096)]:
    item={"case":case,"length":n,"width":width,"samples":[]}
    for iterations in (1,2):
        samples=[]
        for repeat in range(3):
            q=subprocess.run([str(b),"layout",case,str(n),str(iterations),str(width)],capture_output=True,text=True,check=True,env=dict(os.environ,SHODO_EDGE_COUNTS="1",TMPDIR=str(Path.home()/"tmp")))
            data=json.loads(q.stdout)
            signature={k:v for k,v in data.items() if k not in ("measure","iterations")}
            if "output" not in item: item["output"]=signature
            assert signature==item["output"]
            if (case,n,width) in expected: assert signature=={k:v for k,v in expected[case,n,width].items() if k!="iterations"}
            line=re.findall(r"EDGE_COUNTS (.*)",q.stderr)[-1]
            counts={k:int(v) for k,v in re.findall(r"(\w+)=(\d+)",line)}
            samples.append(counts)
        assert samples[0]==samples[1]==samples[2]
        item["samples"].append({"iterations":iterations,"complete_layout_calls":iterations+5,"counts":samples})
    first,second=(s["counts"][0] for s in item["samples"])
    item["seventh_layout_delta"]={k:second[k]-first[k] for k in ("hits","misses","capacity_clears","hit_clones","cloned_glyphs","entry_cap_clears","cost_cap_clears")}
    result.append(item)
    print(case,n,"lines",item["output"]["geometry"]["lines"],"delta",item["seventh_layout_delta"],"max_cost",second["max_cost_before_clear"],flush=True)
(p/"final-observations.json").write_text(json.dumps(result,indent=2)+"\n")

measurement_driver:
import argparse, hashlib, json, os, statistics, subprocess, time
from pathlib import Path
ROOT = Path(__file__).parent
CASES = [('layout','spaces',128,128,40),('layout','spaces',256,128,30),('layout','spaces',1024,128,10),('layout','spaces',4096,128,3),('layout-cold','spaces',256,128,20),('layout-cold','spaces',1024,128,8),('layout-cold','spaces',4096,128,3),('layout-widths','spaces',256,128,10),('layout-widths','spaces',1024,128,3),('layout-widths','spaces',4096,128,1),('layout','plain',4096,1000000,500),('layout','emphasis',4096,1000000,250)]
p = argparse.ArgumentParser(); p.add_argument('kind', choices=['time','alloc']); p.add_argument('--pairs',type=int,default=12); args=p.parse_args()
binaries = {v: ROOT / (v+'-'+args.kind) for v in ['baseline','candidate']}
result = {'kind':args.kind,'cpu':10,'clock':'Instant measured in probe excluding process startup/input/digest/JSON','warmups':3,'samples':[], 'sha256':{v:hashlib.sha256(b.read_bytes()).hexdigest() for v,b in binaries.items()}}
for op,case,n,w,iters in CASES:
    observations={v:[] for v in binaries}; accepted=None
    for i in range(args.pairs):
        order=['baseline','candidate'] if i%2==0 else ['candidate','baseline']
        for v in order:
            command=['taskset','-c','10',str(binaries[v]),op,case,str(n),str(iters),str(w)]
            obs=json.loads(subprocess.check_output(command, text=True, cwd=os.environ['SHODO_WORKTREE']))
            equality={k:obs[k] for k in ['geometry','paint_sha256','width_outputs']}
            if accepted is None: accepted=equality
            assert equality==accepted, (op,case,n,w,v,'output mismatch')
            observations[v].append(obs)
    row={'op':op,'case':case,'length':n,'width':w,'iterations':iters,'pairs':args.pairs,'observations':observations}
    if args.kind=='time':
        meds={v:statistics.median(o['measure']['ns']/iters for o in xs) for v,xs in observations.items()}
        ratios=[observations['candidate'][i]['measure']['ns']/observations['baseline'][i]['measure']['ns'] for i in range(args.pairs)]
        row.update(median_ns_per_iteration=meds,median_paired_ratio=statistics.median(ratios),time_reduction_percent=100*(1-meds['candidate']/meds['baseline']))
        print(op,case,n,w,round(row['time_reduction_percent'],2),flush=True)
    else:
        print(op,case,n,w,observations['baseline'][0]['measure'],observations['candidate'][0]['measure'],flush=True)
    result['samples'].append(row)
    (ROOT/(args.kind+'-samples.json')).write_text(json.dumps(result,indent=2)+'\n')

